const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Inner Niger Delta region (approximate bounds)
  const geometry = ee.Geometry.Polygon([
    [[-5.5, 14.0], [-4.0, 14.0], [-4.0, 15.5], [-5.5, 15.5], [-5.5, 14.0]]
  ]);

  // Function to mask clouds in Sentinel-2
  function maskS2Clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // Get May 2022 data
  const may2022 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(geometry)
    .filterDate('2022-05-01', '2022-05-31')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
    .map(maskS2Clouds)
    .map(addNDVI);

  // Get November 2022 data
  const nov2022 = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(geometry)
    .filterDate('2022-11-01', '2022-11-30')
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80))
    .map(maskS2Clouds)
    .map(addNDVI);

  // Check collection sizes
  const maySize = may2022.size().getInfo();
  const novSize = nov2022.size().getInfo();

  print(`May 2022 Images: ${maySize}`);
  print(`November 2022 Images: ${novSize}`);

  if (maySize === 0 || novSize === 0) {
    print("<answer>C1</answer>");
    return;
  }

  // Create median composites and calculate mean NDVI
  const mayComposite = may2022.median().select('NDVI');
  const novComposite = nov2022.median().select('NDVI');

  // Calculate mean NDVI values
  const mayStats = mayComposite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  });

  const novStats = novComposite.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  });

  const mayNDVI = mayStats.get('NDVI').getInfo();
  const novNDVI = novStats.get('NDVI').getInfo();

  // Check for valid pixels
  const mayCount = mayComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const novCount = novComposite.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  print(`May 2022 NDVI: ${mayNDVI ? mayNDVI.toFixed(3) : 'No data'}, Pixels: ${mayCount}`);
  print(`Nov 2022 NDVI: ${novNDVI ? novNDVI.toFixed(3) : 'No data'}, Pixels: ${novCount}`);

  // Check for no valid pixels
  if (mayCount === 0 || novCount === 0) {
    print("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure
  if (mayNDVI === null || novNDVI === null || 
      isNaN(mayNDVI) || isNaN(novNDVI) ||
      mayNDVI > 1 || mayNDVI < -1 || 
      novNDVI > 1 || novNDVI < -1) {
    print("<answer>C3</answer>");
    return;
  }

  // Determine answer based on NDVI comparison
  if (novNDVI > mayNDVI) {
    print(`Vegetation increased: ${novNDVI.toFixed(3)} > ${mayNDVI.toFixed(3)}`);
    print("<answer>A</answer>");
  } else {
    print(`Vegetation decreased: ${novNDVI.toFixed(3)} <= ${mayNDVI.toFixed(3)}`);
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
